/* @lc app=leetcode id=3493 lang=kotlin */ class Solution { fun find(p: IntArray, x: Int): Int = generateSequence(x) { if (p[it] == it) null else p[it] }.toList().let { path -> path.last().also { r -> path.forEach { p[it] = r } } } fun numberOfComponents(properties: Array<IntArray>, k: Int): Int = properties.map { it.toSet() }.let { sets -> IntArray(sets.size) { it }.let { p -> sets.indices.forEach { i -> (i + 1 until sets.size).forEach { j -> if ((sets[i] intersect sets[j]).size >= k) p[find(p, i)] = find(p, j) } }.let { sets.indices.map { find(p, it) }.distinct().size } } } }